const setChannelNumbers = `-- name: SetChannelNumbers :exec
UPDATE channels SET number = ($1::int[])[array_position($2::bigint[], id)], updated_at = now()
WHERE id = ANY($2::bigint[])
`

type SetChannelNumbersParams struct {
	Numbers []int32 `json:"numbers"`
	Ids     []int64 `json:"ids"`
}

// ids[i] gets numbers[i].
func (q *Queries) SetChannelNumbers(ctx context.Context, arg SetChannelNumbersParams) error {
	_, err := q.db.Exec(ctx, setChannelNumbers, arg.Numbers, arg.Ids)
	return err
}

const setChannelsGroup = `-- name: SetChannelsGroup :execrows
UPDATE channels SET group_id = $1, updated_at = now()
WHERE id = ANY($2::bigint[])
  AND group_id IS DISTINCT FROM $1
`

type SetChannelsGroupParams struct {
	GroupID    *int64  `json:"group_id"`
	ChannelIds []int64 `json:"channel_ids"`
}

// Moves channels into a group (NULL = no group).
func (q *Queries) SetChannelsGroup(ctx context.Context, arg SetChannelsGroupParams) (int64, error) {
	result, err := q.db.Exec(ctx, setChannelsGroup, arg.GroupID, arg.ChannelIds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setupProgress = `-- name: SetupProgress :one
SELECT
    (SELECT count(*) FROM providers)::bigint AS providers,
    (SELECT count(*) FROM provider_streams WHERE NOT disabled)::bigint AS streams,
    (SELECT count(*) FROM providers WHERE group_filter)::bigint AS filtered_providers,
    (SELECT count(*) FROM channels)::bigint AS channels,
    (SELECT count(*) FROM bouquets b WHERE EXISTS (SELECT 1 FROM bouquet_channels bc WHERE bc.bouquet_id = b.id))::bigint AS bouquets,
    (SELECT count(*) FROM users u WHERE u.role = 'customer'
        AND EXISTS (SELECT 1 FROM user_bouquets ub WHERE ub.user_id = u.id))::bigint AS customers
`

type SetupProgressRow struct {
	Providers         int64 `json:"providers"`
	Streams           int64 `json:"streams"`
	FilteredProviders int64 `json:"filtered_providers"`
	Channels          int64 `json:"channels"`
	Bouquets          int64 `json:"bouquets"`
	Customers         int64 `json:"customers"`
}

// Counts behind the dashboard's setup checklist.
func (q *Queries) SetupProgress(ctx context.Context) (SetupProgressRow, error) {
	row := q.db.QueryRow(ctx, setupProgress)
	var i SetupProgressRow
	err := row.Scan(
		&i.Providers,
		&i.Streams,
		&i.FilteredProviders,
		&i.Channels,
		&i.Bouquets,
		&i.Customers,
	)
	return i, err
}

